const PROMPT_ASIRI = "Sos Asiri, la secretaria virtual de la Dra. Raquel Rodríguez (Áurea Odontología Estética, San Salvador de Jujuy). Atendés por WhatsApp a pacientes y familias.\n\nCÓMO HABLÁS\n- De \"usted\", frases cortas y una sola pregunta por vez. Respondé a lo que el paciente dice, con sus datos: nunca contestes con un texto genérico ni repitas el mismo mensaje.\n- Presentate (\"Soy Asiri, la secretaria virtual de la Dra. Raquel\") solo en el primer mensaje de una conversación nueva o tras un recordatorio.\n- Cuando una herramienta te devuelve un texto para el paciente (el bloque de horarios o el texto de confirmación), tu respuesta ES ese texto, tal cual. Podés agregar una frase corta antes; nunca lo cambies ni lo resumas.\n\nCÓMO FUNCIONA EL CONSULTORIO\n- Es un consultorio privado: se atiende solo con turno previo. No hay guardia ni atención las 24 hs. Si alguien quiere ir sin turno, explicale cómo funciona y ofrecele sacar uno.\n- Está bien decir \"lo esperamos el día de su turno\". Nunca invites a ir ahora ni sin turno.\n- Por ser menor, el tutor debe estar presente.\n- Pagos: informás los datos para abonar y recibís comprobantes. No validás montos ni decís que un pago ingresó: lo verifica la secretaria.\n\nQUÉ HACÉS (con tus herramientas, nunca de memoria). Arriba de cada mensaje el sistema ya te trae los DATOS DE ESTE CELULAR EN LA AGENDA (fichas y turnos vigentes): no llames ver_turnos salvo para refrescarlos tras un cambio.\n- Quiere un turno nuevo: llamá buscar_horarios de una y pegá el bloque. No le preguntes franja, fecha ni para quién es antes de ofrecerle horarios.\n- Si pidió una franja o fecha y el bloque no la cumple (pidió tarde y solo hay mañanas), decíselo en una frase antes del bloque.\n- Elige un horario que YA le ofreciste: llamá proponer, sin volver a buscar horarios. Si el celular tiene varias fichas (familia) y no sabés para quién es, preguntalo (nombre o DNI) y usá elegir_ficha. Si proponer te pide ver_turnos, llamala y reintentá.\n- Quiere cambiar o cancelar un turno: su turno ya figura en los DATOS (ver_turnos solo si no figura). Cambio: buscar_horarios y proponer tipo cambio. Cancelar: proponer tipo cancelacion.\n- proponer te devuelve el texto de confirmación: pegalo TEXTUAL y esperá el \"sí\" del paciente en su PRÓXIMO mensaje; recién ahí llamá ejecutar_propuesta. Nunca ejecutes en el mismo mensaje en que proponés.\n- Si el paciente contesta una pregunta o propuesta del STAFF (\"sí, a las 17\"), no abras un trámite nuevo: avisá con avisar_grupo ACCION su respuesta textual y decile que ya se lo avisaste a la secretaria.\n- Responde a un recordatorio (\"confirmo\", \"ahí estaremos\"): confirmar_turno (si hay varios pendientes, una vez por fecha).\n- Dudas de datos (precio, horarios de atención, cómo pagar, dónde queda): respondé con los DATOS DEL CONSULTORIO, sin llamar herramientas.\n- No repitas ver_turnos ni buscar_horarios si ya los llamaste y nada cambió.\n- Decí que algo quedó hecho SOLO si la herramienta lo confirmó. Si una herramienta falla (p. ej. se ocupó el horario), contá con sinceridad qué pasó, aclará que su turno actual sigue igual y ofrecé el siguiente horario.\n- Avisar a la clínica sin dejar de atender: avisar_grupo (FYI o ACCION). Comprobante de pago o \"ya transferí\": registrar_pago. Pide que lo anoten por si se libera un turno: lista_espera (decí solo \"se lo dejo anotado a la clínica\"; no prometas que le van a avisar). No uses estas dos para cosas que podés resolver vos.\n\nURGENCIAS (dolor, molestia, sangrado, hinchazón, golpe, no puede comer, aparato/alambre/bracket roto, suelto o que pincha): llamá derivar_triaje y respondé exactamente [NO_REPLY]; la clínica le contesta. Ante la duda, derivá.\n\nPASAR A UNA PERSONA (pasar_a_humano): solo si pide hablar con una persona (secretaria, doctora), se queja o pide la baja de sus datos. Lo demás lo resolvés vos.\n\nLÍMITES\n- No das diagnósticos ni opinás sobre síntomas; no indicás medicación ni cuidados. Ante una consulta clínica, decí que la doctora se lo responde y avisá a la clínica.\n- No des la dirección salvo que la pidan. No inventes horarios, precios ni datos: usá solo los DATOS DEL CONSULTORIO que figuran abajo.\n- Si el mensaje es solo un cierre (\"gracias\", \"ok\", \"listo\") y no hay nada pendiente, respondé exactamente [NO_REPLY].";
// historial_core.js — v7 · el contexto de la conversación que ve Asiri. Fuente de verdad en el repo (se inlinea en un nodo Code de n8n).
// Reemplaza al nodo de memoria sin filtro: arma los últimos turnos REALES desde n8n_chat_histories (más nuevo primero), acorta los marcadores del staff
// (250 caracteres de "[ATENCION HUMANA - ...]" en cada llamada era ruido) y descarta las etiquetas internas del Router viejo.
const HistorialCore = (() => {
  const ETIQUETAS_ROUTER = new Set(['cancelar_o_reprogramar', 'confirmar', 'agendar', 'urgencia', 'consulta_general', 'general', 'pago', 'derivar', 'silencio', 'no_reply', 'cancelar', 'reprogramar',
    'confirmar_post_recordatorio', 'agendar_nuevo', 'urgencia_dolor']);
  const corta = (s, n) => { const t = String(s || '').replace(/\s+/g, ' ').trim(); return t.length > n ? t.slice(0, n - 1) + '…' : t; };

  // rows: [{ message: {type, content, additional_kwargs?} | string JSON }] ordenadas del MÁS NUEVO al más viejo (como las devuelve la consulta).
  function armar(rows, max) {
    const turnos = [];
    for (const r of rows || []) {
      let m = r && r.message;
      if (typeof m === 'string') { try { m = JSON.parse(m); } catch (e) { continue; } }
      if (!m || typeof m !== 'object') continue;
      const c = String(m.content || '').trim();
      if (!c) continue;
      const src = (m.additional_kwargs || {}).source;
      if (m.type === 'human') turnos.push('PACIENTE: ' + corta(c, 500));
      else if (m.type === 'ai') {
        if (ETIQUETAS_ROUTER.has(c.toLowerCase())) continue;
        if (/^\[ATENCION HUMANA/i.test(c)) turnos.push('STAFF DE LA CLÍNICA (persona): ' + corta(c.replace(/^\[ATENCION HUMANA[^\]]*\]:?\s*/i, ''), 220));
        else if (/^\[NOTA INTERNA/i.test(c)) continue;
        else if (src === 'reminder_note' || /le recordamos su turno|recordamos que el d[ií]a/i.test(c)) turnos.push('CLÍNICA (recordatorio enviado): ' + corta(c, 260));
        else turnos.push('ASIRI: ' + corta(c, 700));
      }
      if (turnos.length >= (max || 12)) break;
    }
    return turnos.reverse();   // cronológico: lo más nuevo al final
  }
  // Texto único que se le pasa al agente como mensaje de usuario.
  // `ident` = salida de la herramienta ver_turnos (ya resuelta por el código ANTES de que Asiri responda): fichas del celular y turnos vigentes.
  function identidad(ident) {
    const i = ident || {};
    if (i.ok === true) {
      const t = (i.turnos && i.turnos.length) ? 'Turnos vigentes: ' + i.turnos.join('; ') + '.' : 'No tiene turnos vigentes.';
      if (i.varias_fichas) {
        return 'Pacientes con este celular: ' + (i.pacientes || []).join(', ') + '. ' + (i.ficha_elegida ? 'Ya está elegido: ' + (i.paciente_elegido || '') + '. ' : 'TODAVÍA no sabés para quién es: igual buscá y ofrecé horarios, y en el MISMO mensaje preguntá para quién es (nombre o DNI); elegir_ficha hace falta recién para proponer. ') + t;
      }
      return 'Paciente de este celular: ' + (i.paciente_elegido || '(una ficha)') + '. ' + t;
    }
    return 'No pude consultar la ficha o la agenda en este momento' + (i.motivo ? ' (' + i.motivo + ')' : '') + '. No inventes turnos; para consultas de datos del consultorio seguí normal, y si necesitás la agenda avisá a la clínica con avisar_grupo.';
  }
  function mensajeAgente(historial, mensaje, ahoraJujuy, recordatorios, pushName, ident) {
    const partes = [];
    partes.push('FECHA Y HORA ACTUAL (Jujuy): ' + ahoraJujuy);
    if (pushName) partes.push('Nombre en WhatsApp de quien escribe: ' + corta(pushName, 40) + ' (puede ser un familiar y no el paciente).');
    if (ident !== undefined) partes.push('DATOS DE ESTE CELULAR EN LA AGENDA (ya consultados por el sistema): ' + identidad(ident));
    if (recordatorios && recordatorios.length) partes.push('RECORDATORIOS PENDIENTES DE CONFIRMAR: ' + recordatorios.join(' | '));
    partes.push('CONVERSACIÓN RECIENTE (lo más nuevo abajo):\n' + (historial.length ? historial.join('\n') : '(es la primera vez que escribe)'));
    partes.push('MENSAJE ACTUAL DEL PACIENTE:\n' + mensaje);
    return partes.join('\n\n');
  }
  // ---------------------------------------------------------------------------------------------------- cierres de conversación ("gracias", "ok", "si, gracias")
  // Un agradecimiento / despedida PURO no necesita respuesta: se corta ANTES de llamar al modelo (sin costo, sin demora y sin el "De nada! Quedo a disposición para…" genérico
  // ni el "ya le transmito su consulta a la secretaria"). El 27/05 se había sacado el filtro conversacional porque mataba "Confirmamos turno gracias": por eso este exige que el
  // mensaje sean SOLO palabras de cierre (+ a lo sumo un nombre), y el pipeline lo anula si lo último que se le dijo al paciente fue una pregunta o hay un recordatorio sin confirmar.
  const sinT = (x) => String(x || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const PALABRAS_CIERRE = new Set(['gracias', 'ok', 'oka', 'okey', 'okk', 'dale', 'listo', 'perfecto', 'genial', 'buenisimo', 'excelente', 'joya', 'barbaro', 'entendido', 'chau', 'saludos', 'abrazo', 'abrazos', 'igualmente', 'luego', 'vemos', 'pronto', 'hasta']);
  const RELLENO = new Set(['si', 'sii', 'siii', 'bien', 'muy', 'muchas', 'muchisimas', 'mil', 'de', 'nada', 'acuerdo', 'a', 'usted', 'todo', 'un', 'nos', 'que', 'tenga', 'buen', 'buena', 'dia', 'tarde', 'noche', 'lindo', 'linda', 'descanse', 'hasta', 'ya', 'recibido', 'queda', 'asi', 'y', 'tambien', 'igual']);
  function esCierre(texto) {
    const crudo = String(texto || '');
    if (/[?¿]/.test(crudo) || crudo.length > 70) return false;
    const t = sinT(crudo).replace(/[\p{Extended_Pictographic}‍️\u{1F3FB}-\u{1F3FF}]/gu, ' ').replace(/[^a-z\s]/g, ' ').replace(/\s+/g, ' ').trim();
    if (!t) return false;                                   // solo emojis: lo resuelve el pre-filtro técnico del v6, acá no se decide
    const toks = t.split(' ');
    if (toks.length > 8 || !toks.some((w) => PALABRAS_CIERRE.has(w))) return false;
    let nombres = 0;
    for (const w of toks) {
      if (PALABRAS_CIERRE.has(w) || RELLENO.has(w)) continue;
      if (/^[a-z]{3,12}$/.test(w) && toks.includes('gracias')) { nombres++; continue; }   // "Gracias Iris", "Muchas gracias Iri"
      return false;
    }
    return nombres <= 1;
  }
  // ¿Lo último que se le dijo al paciente (Asiri, el staff o un recordatorio) le pedía una respuesta? Si sí, "si, gracias" NO es un cierre: es la respuesta.
  function ultimoPideRespuesta(hist) {
    for (let i = (hist || []).length - 1; i >= 0; i--) {
      const l = String(hist[i]);
      if (/^PACIENTE:/.test(l)) continue;
      return /[?¿]/.test(l) || /confirmar su asistencia|confirme su asistencia|responda|respondiendo a este mensaje|necesito|pasame|pásame/i.test(l);
    }
    return false;
  }
  return { armar, mensajeAgente, identidad, corta, esCierre, ultimoPideRespuesta };
})();
if (typeof module !== 'undefined') module.exports = HistorialCore;
const e = $('Entrada').first().json;
const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
let override = null; try { override = e.historial_json ? JSON.parse(e.historial_json) : null; } catch (x) { override = null; }
const filas = Array.isArray(override) ? override : $('Historial').all().map((i) => i.json).filter((r) => r && r.message);
const hist = HistorialCore.armar(filas, 12);
const rec = $('Recordatorios').all().map((i) => i.json).filter((r) => r && r.id_cita_dentalink && r.fecha_turno).map((r) => {
  const f = String(r.fecha_turno).slice(0, 10);
  return DIAS[new Date(f + 'T12:00:00Z').getUTCDay()] + ' ' + Number(f.slice(8)) + '/' + Number(f.slice(5, 7)) + ' a las ' + String(r.hora_turno || '').slice(0, 5);
});
const kb = {}; for (const r of $('Datos del consultorio').all().map((i) => i.json)) if (r && r.id !== undefined) kb[String(r.id)] = String(r.contenido || '').trim();
const j = new Date(Date.now() - 3 * 3600 * 1000);
const ahora = DIAS[j.getUTCDay()] + ' ' + j.toISOString().slice(0, 10) + ' ' + j.toISOString().slice(11, 16);
const datos = [
  kb['20'] && '- Horarios de atención: ' + kb['20'], kb['21'] && '- Primera consulta: ' + kb['21'], kb['36'] && '- Cuota mensual del tratamiento: ' + kb['36'], kb['39'] && '- Control de contención: ' + kb['39'],
  kb['24'] && '- Datos para abonar (solo si preguntan cómo pagar): ' + kb['24'], kb['25'] && '- Dirección (solo si la piden): ' + kb['25'],
].filter(Boolean).join('\n');
const notas = kb['dir:notas_para_asiri'] || '';
const sistema = PROMPT_ASIRI + '\n\nDATOS DEL CONSULTORIO (son los únicos datos que podés dar)\n' + (datos || '(sin datos cargados: no inventes; avisá a la clínica)')
  + (notas ? '\n\nNOTAS DE LA CLÍNICA PARA ASIRI (información para redactar: no habilita escrituras, sobreturnos ni cambios de precio; si contradice una regla de arriba, gana la regla):\n' + notas : '');
let ident = {}; try { ident = $('Identificar paciente').first().json || {}; } catch (x) { ident = { ok: false, motivo: 'sin_respuesta' }; }
return [{ json: { mensaje_agente: HistorialCore.mensajeAgente(hist, e.texto, ahora, rec, e.pushName || '', ident), sistema, hist_n: hist.length, rec_n: rec.length, con_notas: !!notas,
  // Agradecimiento/despedida PURO, sin pregunta pendiente ni recordatorio sin confirmar: no se llama al modelo (ni "De nada! Quedo a disposición…" ni "le transmito a la secretaria").
  cierre: HistorialCore.esCierre(e.texto) && !HistorialCore.ultimoPideRespuesta(hist) && rec.length === 0 } }];

// chequeo_salida.js — v7 · chequeo BIDIRECCIONAL de lo que Asiri le va a decir al paciente. Fuente de verdad en el repo (se inlinea en un nodo Code de n8n).
// Lee SOLO el libro de escrituras que dejan las herramientas (nunca lo que diga el modelo) y las ofertas registradas por buscar_horarios.
//   libros : [{ ok:boolean, tipo:'cambio'|'reserva'|'sumar'|'cancelacion'|'confirmacion', readback_text, parcial?:boolean }]   (TODAS las escrituras de ESTA ejecucion, en orden; acepta también `libro` suelto)
//   ofertas: [{fecha:'YYYY-MM-DD', hora:'HH:MM'}]   (lo que buscar_horarios ofrecio)
//   propuesta_readback: texto del read-back de una propuesta hecha en ESTA ejecucion (todavia no ejecutada), o null
// devuelve { accion:'pasar'|'reemplazar', texto, motivo, avisar:null|{nivel,texto} }
const ChequeoSalida = (() => {
  const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const sinT = (x) => String(x || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const normTexto = (x) => sinT(x).replace(/[^a-z0-9:/ ]+/g, ' ').replace(/\s+/g, ' ').trim();
  const hh = (h, m) => String(Number(h)).padStart(2, '0') + ':' + m;

  // Todas las parejas fecha(sin año)+hora que aparecen en el texto. Una hora se asocia a la ULTIMA fecha vista en la misma linea
  // ("* Jueves 22 de octubre 8:00 , 9:20" → dos parejas; "el jueves 22/10 a las 09:20" → una).
  function parejas(texto) {
    const out = [];
    for (const linea of String(texto || '').split('\n')) {
      const l = sinT(linea);
      const tokens = [];
      for (const m of l.matchAll(/(\d{1,2})\s+de\s+([a-z]+)/g)) { const mes = MESES.indexOf(m[2] === 'setiembre' ? 'septiembre' : m[2]) + 1; if (mes) tokens.push({ i: m.index, tipo: 'f', md: `${String(mes).padStart(2, '0')}-${String(Number(m[1])).padStart(2, '0')}` }); }
      for (const m of l.matchAll(/\b(\d{1,2})\/(\d{1,2})\b/g)) tokens.push({ i: m.index, tipo: 'f', md: `${String(Number(m[2])).padStart(2, '0')}-${String(Number(m[1])).padStart(2, '0')}` });
      for (const m of l.matchAll(/\b(\d{1,2}):(\d{2})\b/g)) tokens.push({ i: m.index, tipo: 'h', h: hh(m[1], m[2]) });
      tokens.sort((a, b) => a.i - b.i);
      let fecha = null;
      for (const t of tokens) { if (t.tipo === 'f') fecha = t.md; else if (fecha) out.push(`${fecha} ${t.h}`); }
    }
    return out;
  }
  const clave = (o) => `${o.fecha.slice(5)} ${String(o.hora).replace(/^(\d):/, '0$1:')}`;

  // "Afirmaciones de haber hecho algo". Solo formas conjugadas que dicen "ya esta hecho"; "le confirmo:" (read-back) y "confirme su asistencia" NO cuentan.
  // Limites de palabra UNICODE: el \b de JavaScript no sirve pegado a una letra con tilde ("agendé", "moví").
  const W = (src) => new RegExp(String.raw`(?<![\p{L}])(?:` + src + String.raw`)(?![\p{L}])`, 'iu');
  const CLAIMS = [
    { tipo: 'reprogramar', rx: W(String.raw`qued(?:ó|o|a|an)\s+(?:reprogramad|cambiad|movid|reservad|agendad)\p{L}*|qued(?:ó|a)\s+anotad\p{L}*\s+(?:el|su|un)\s+turno|reprogramé|cambié|moví|reservé|agendé|anot[eé]\s+(?:su|el|un)\s+turno|(?:le|lo|la)\s+(?:reserve|agende|cambie|movi|reprograme)|ya\s+(?:le\s+)?(?:reserv|agend|cambi|mov|anot)\p{L}*|le\s+dej[oé]\s+(?:reservad|agendad|anotad)\p{L}*|list[oa],?\s+(?:reprogramad|reservad|agendad|cambiad)\p{L}*`) },
    { tipo: 'cancelar', rx: W(String.raw`qued(?:ó|o|a|an)\s+cancelad\p{L}*|cancelé|anulé|(?:le|lo|la)\s+(?:cancele|anule)|list[oa],?\s+(?:cancelad|anulad)\p{L}*`) },
    { tipo: 'confirmar', rx: W(String.raw`qued(?:ó|o|a|an)\s+confirmad\p{L}*|confirmé|list[oa],?\s+confirmad\p{L}*`) },
  ];
  const TIPOS_OK = { reprogramar: ['cambio', 'reserva', 'sumar'], cancelar: ['cancelacion'], confirmar: ['confirmacion'] };
  const esc = (x) => String(x).replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+');
  const quitar = (texto, frase) => (frase ? String(texto).replace(new RegExp(esc(frase), 'gi'), ' ') : texto);
  const honesto = 'Disculpe, todavía no pude concretar eso en la agenda, así que no quedó hecho. Le aviso a la clínica para que lo resuelva y se comunique con usted.';

  function revisar(entrada) {
    const texto = String(entrada.texto || '');
    const libros = Array.isArray(entrada.libros) ? entrada.libros : (entrada.libro ? [entrada.libro] : []);
    const oks = libros.filter((l) => l && l.ok === true);
    const libro = oks.length ? oks[oks.length - 1] : (libros.length ? libros[libros.length - 1] : null);   // el que tiene que contar el texto: la última escritura ok
    const ofertas = entrada.ofertas || [];
    const nTexto = normTexto(texto);
    const hechoOk = oks.length > 0;

    // (1) hay una escritura OK y el texto no contiene el read-back de lo que se hizo (timeout / maxIterations / el modelo se fue por las ramas)
    const sinDecir = oks.filter((l) => l.readback_text && !nTexto.includes(normTexto(l.readback_text)));
    if (hechoOk && sinDecir.length === oks.length && libro.readback_text) {
      // (3) ...y ademas habla de OTRA fecha+hora distinta: tambien se reemplaza (mismo remedio: decir lo que realmente paso)
      return { accion: 'reemplazar', texto: libro.readback_text, motivo: parejas(texto).length ? 'fecha_distinta_a_la_escrita' : 'falta_confirmacion_de_lo_hecho', avisar: { nivel: 'tecnico', texto: 'El chequeo de salida reemplazó el mensaje de Asiri por el resultado real de la agenda.' } };
    }
    const parcial = libros.find((l) => l && l.parcial === true && l.readback_text && !nTexto.includes(normTexto(l.readback_text)));
    if (parcial) {
      return { accion: 'reemplazar', texto: parcial.readback_text, motivo: 'escritura_parcial_sin_decirlo', avisar: { nivel: 'ACCION', texto: 'Escritura parcial: revisar la agenda.' } };
    }

    // (1b) lo que el CÓDIGO le dio a Asiri para que pegue textual (el read-back de una propuesta de esta ejecución; el bloque de horarios recién buscado) tiene que
    // llegar al paciente. Si el modelo se lo salteó, se reemplaza por ese texto: sin él la charla se traba (el paciente no ve las opciones / no tiene qué confirmar).
    if (entrada.propuesta_readback && !nTexto.includes(normTexto(entrada.propuesta_readback))) {
      return { accion: 'reemplazar', texto: entrada.propuesta_readback, motivo: 'falta_readback', avisar: { nivel: 'tecnico', texto: 'Asiri no pegó el texto de confirmación; se envió el armado por el código.' } };
    }
    if (entrada.bloque_exec && !nTexto.includes(normTexto(entrada.bloque_exec))) {
      return { accion: 'reemplazar', texto: entrada.bloque_exec, motivo: 'falta_bloque', avisar: { nivel: 'tecnico', texto: 'Asiri no pegó el bloque de horarios; se envió el armado por el código.' } };
    }

    // (2) afirma que algo quedó hecho y NO hay una escritura OK compatible
    // Se evalua sobre el texto SIN los read-backs que el propio codigo escribio (el de la escritura, el de la propuesta): esos dicen la verdad.
    let sobrante = String(texto);
    for (const l of libros) sobrante = quitar(sobrante, l && l.readback_text);
    sobrante = quitar(sobrante, entrada.propuesta_readback);
    if (!(propuestaVigente(entrada))) {
      for (const c of CLAIMS) {
        if (!c.rx.test(sobrante)) continue;
        const compatible = oks.some((l) => TIPOS_OK[c.tipo].includes(l.tipo));
